import { realpathSync } from "node:fs";
import { pathToFileURL } from "node:url";
import {
  loadConfig,
  BithumbRestClient,
  createToolRunner,
  TradeLogger,
  checkForUpdates,
} from "@bithumb-official/bithumb-core";
import type { ToolRunner } from "@bithumb-official/bithumb-core";
import { parseCli, CliUsageError } from "./parser.js";
import type { CliValues } from "./parser.js";
import { outputLine, errorLine } from "./formatter.js";
import { printHelp } from "./help/index.js";
import { CLI_VERSION } from "./constants.js";

function wrapRunnerWithLogger(
  baseRunner: ToolRunner,
  logger: TradeLogger,
): ToolRunner {
  return async (toolName, args) => {
    const start = Date.now();
    try {
      const result = await baseRunner(toolName, args);
      logger.logTool("info", toolName, args, { status: "ok" }, Date.now() - start);
      return result;
    } catch (error) {
      logger.logTool("error", toolName, args, error, Date.now() - start);
      throw error;
    }
  };
}

export async function main(): Promise<void> {
  checkForUpdates("@bithumb-official/bithumb-cli", CLI_VERSION);

  // 1. Parse arguments
  let parsed: ReturnType<typeof parseCli>;
  try {
    parsed = parseCli(process.argv.slice(2));
  } catch (err) {
    if (err instanceof CliUsageError) {
      errorLine(`Error: ${err.message}. Run 'bithumb --help' for usage.`);
      process.exitCode = 1;
      return;
    }
    throw err;
  }
  const { values: v, positionals } = parsed;

  if (v.version) {
    outputLine(CLI_VERSION);
    return;
  }

  if (v.help || positionals.length === 0) {
    await printHelp(positionals);
    return;
  }

  const [module, action, ...rest] = positionals;
  const json = v.json ?? false;

  // 3. Config command (no auth needed, no runner needed)
  if (module === "config") {
    const { handleConfigCommand } = await import("./commands/config.js");
    return handleConfigCommand(action, rest, v);
  }

  // 4. Load config + create runner
  const config = loadConfig({
    modules: v.modules,
    verbose: v.verbose,
    profile: v.profile,
    clientType: "cli",
  });
  const client = new BithumbRestClient(config);
  const baseRunner = createToolRunner(client, config);
  const logger = new TradeLogger({
    minLevel: v.verbose ? "debug" : "info",
    emitToStderr: v.verbose ?? false,
    verbose: v.verbose ?? false,
  });
  const run = wrapRunnerWithLogger(baseRunner, logger);

  // 5. System module (no auth needed) — capabilities + diagnose + audit
  if (module === "system") {
    try {
      const { handleSystemCommand } = await import("./commands/system.js");
      return await handleSystemCommand(run, action, v, json);
    } catch (err) {
      if (err instanceof CliUsageError) {
        errorLine(`Error: ${err.message}`);
        process.exitCode = 1;
        return;
      }
      throw err;
    }
  }

  // 6. Private API auth guard
  const privateModules = new Set(["account", "trade", "twap", "withdraw", "deposit"]);
  if (privateModules.has(module) && !config.hasAuth) {
    errorLine(
      "Error: API credentials required. Set BITHUMB_ACCESS_KEY/BITHUMB_SECRET_KEY env vars or run 'bithumb config init'.",
    );
    process.exitCode = 1;
    return;
  }

  // 7. Module routing
  try {
    if (module === "market") {
      const { handleMarketCommand } = await import("./commands/market.js");
      return await handleMarketCommand(run, action, rest, v, json);
    }
    if (module === "account") {
      const { handleAccountCommand } = await import("./commands/account.js");
      return await handleAccountCommand(run, action, v, json);
    }
    if (module === "trade") {
      const { handleTradeCommand } = await import("./commands/trade.js");
      return await handleTradeCommand(run, action, v, json);
    }
    if (module === "twap") {
      const { handleTwapCommand } = await import("./commands/twap.js");
      return await handleTwapCommand(run, action, v, json);
    }
    if (module === "withdraw") {
      const { handleWithdrawCommand } = await import("./commands/withdraw.js");
      return await handleWithdrawCommand(run, action, v, json);
    }
    if (module === "deposit") {
      const { handleDepositCommand } = await import("./commands/deposit.js");
      return await handleDepositCommand(run, action, v, json);
    }
  } catch (err) {
    if (err instanceof CliUsageError) {
      errorLine(`Error: ${err.message}`);
      process.exitCode = 1;
      return;
    }
    throw err;
  }

  errorLine(`Unknown command: ${module}. Run 'bithumb --help' for usage.`);
  process.exitCode = 1;
}

// Run main only when executed as a script (not when imported by tests).
// Use realpath to handle invocation through npm bin symlinks (e.g. `bithumb`).
function isDirectInvocation(): boolean {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return import.meta.url === pathToFileURL(realpathSync(entry)).href;
  } catch {
    return import.meta.url === pathToFileURL(entry).href;
  }
}

if (isDirectInvocation()) {
  main().catch((err) => {
    errorLine(`Fatal: ${err instanceof Error ? err.message : String(err)}`);
    process.exitCode = 1;
  });
}
